const P = { minLon: -79.00879935755839, maxLat: 12.459569580703594, k: 0.9974219286168177, s: 46.165652008321075, pad: 10 };

/** Proyecta longitud/latitud a coordenadas del SVG (misma proyección de las geometrías). */
export function proyectar(lon: number, lat: number): { x: number; y: number } {
  return { x: (lon - P.minLon) * P.k * P.s + P.pad, y: (P.maxLat - lat) * P.s + P.pad };
}

